INSERT INTO collection_pages VALUES('1f7bd7bdac8fd23728a2779c75e256f8849ede353bc6e1364b3412fc0a762ccd','47fc48ae415cacd6e11256e4c4de022dffe9af20093182301fe4f88b5f097608','{"hasNext":false,"items":[{"author":{"account":null,"email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"authoredDate":"2026-10-05T07:43:36Z","committedDate":"2026-10-05T07:43:36Z","committer":{"account":null,"email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"observedAt":"2026-10-09T00:56:25.121Z","repositoryId":1404475013,"sha":"549a6f8efca59e2e4ab371ccea677c5044cfcd2a"},{"author":{"account":null,"email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"authoredDate":"2026-10-04T13:59:21Z","committedDate":"2026-10-04T13:59:21Z","committer":{"account":null,"email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"observedAt":"2026-10-09T00:56:25.121Z","repositoryId":1404475013,"sha":"395d703a44c724cdf510b8f127894c29817cb6a6"}],"observedAt":"2026-10-09T00:56:25.121Z","raw":[{"author":null,"comments_url":"https://api.github.com/repos/Rabby-khan-04/next-doc/commits/549a6f8efca59e2e4ab371ccea677c5044cfcd2a/comments","commit":{"author":{"date":"2026-10-05T07:43:36Z","email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"comment_count":0,"committer":{"date":"2026-10-05T07:43:36Z","email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"message":"docs: add CHEATSHEET.md and RECALL.md (3am-proof companions to the handbook)\n\nTwo new top-level documents covering the same 235 topics as the handbook:\n\nCHEATSHEET.md (18.8k lines, 12.2k table rows)\n- Dense lookup tables only: exact signatures, defaults, enum values, prop\n  tables, config options, and an error-text -> fix decoder.\n- Zero prose. Cross-references use bare serials (see **NNN**).\n- Ends with \"The 3am panic card\": 18 questions that cover most of what gets\n  asked, answerable in one sentence each.\n\nRECALL.md (10.3k lines, 235 cards)\n- One spoken-answer card per topic: a Q phrased the way a person would ask\n  it, a 30-second plain-English answer, two follow-ups that separate\n  recognition from understanding, and the trap (the mistake everyone makes).\n- Same 26-part order as the handbook, so serials line up.\n\nVerification: 235/235 serials have a card; 0 ragged table rows in the cheat\nsheet; heading hierarchy normalised to one H1 per part.\n\nCo-Authored-By: Claude Opus 4.8 (1M context) <noreply@anthropic.com>","tree":{"sha":"60d3f401b6a3ee85ba03bab907e272a51eb93400","url":"https://api.github.com/repos/Rabby-khan-04/next-doc/git/trees/60d3f401b6a3ee85ba03bab907e272a51eb93400"},"url":"https://api.github.com/repos/Rabby-khan-04/next-doc/git/commits/549a6f8efca59e2e4ab371ccea677c5044cfcd2a","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/Rabby-khan-04/next-doc/commit/549a6f8efca59e2e4ab371ccea677c5044cfcd2a","node_id":"C_kwDOU7aWhdoAKDU0OWE2ZjhlZmNhNTllMmU0YWIzNzFjY2VhNjc3YzUwNDRjZmNkMmE","parents":[{"html_url":"https://github.com/Rabby-khan-04/next-doc/commit/395d703a44c724cdf510b8f127894c29817cb6a6","sha":"395d703a44c724cdf510b8f127894c29817cb6a6","url":"https://api.github.com/repos/Rabby-khan-04/next-doc/commits/395d703a44c724cdf510b8f127894c29817cb6a6"}],"sha":"549a6f8efca59e2e4ab371ccea677c5044cfcd2a","url":"https://api.github.com/repos/Rabby-khan-04/next-doc/commits/549a6f8efca59e2e4ab371ccea677c5044cfcd2a"},{"author":null,"comments_url":"https://api.github.com/repos/Rabby-khan-04/next-doc/commits/395d703a44c724cdf510b8f127894c29817cb6a6/comments","commit":{"author":{"date":"2026-10-04T13:59:21Z","email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"comment_count":0,"committer":{"date":"2026-10-04T13:59:21Z","email":"ajrabby72@gmail.com","name":"Rabby-khan-04"},"message":"feat(doc): created learning doc of next.js","tree":{"sha":"42c24fb71febe46648ce36b8afe92998475a799a","url":"https://api.github.com/repos/Rabby-khan-04/next-doc/git/trees/42c24fb71febe46648ce36b8afe92998475a799a"},"url":"ht