iga também as animações de View Transition;\n  as demais já eram zeradas em base.css e usam motion-safe.","tree":{"sha":"81d24ae70fa6aaeb098b50442fcb7f8c6f50e8d1","url":"https://api.github.com/repos/eduardomds96/nexo-filmes/git/trees/81d24ae70fa6aaeb098b50442fcb7f8c6f50e8d1"},"url":"https://api.github.com/repos/eduardomds96/nexo-filmes/git/commits/41042319f4c292b4ef2ccb9c9bc27ae5ec856c6d","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/195802856?v=4","events_url":"https://api.github.com/users/eduardomds96/events{/privacy}","followers_url":"https://api.github.com/users/eduardomds96/followers","following_url":"https://api.github.com/users/eduardomds96/following{/other_user}","gists_url":"https://api.github.com/users/eduardomds96/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/eduardomds96","id":195802856,"login":"eduardomds96","node_id":"U_kgDOC6u26A","organizations_url":"https://api.github.com/users/eduardomds96/orgs","received_events_url":"https://api.github.com/users/eduardomds96/received_events","repos_url":"https://api.github.com/users/eduardomds96/repos","site_admin":false,"starred_url":"https://api.github.com/users/eduardomds96/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/eduardomds96/subscriptions","type":"User","url":"https://api.github.com/users/eduardomds96","user_view_type":"public"},"html_url":"https://github.com/eduardomds96/nexo-filmes/commit/41042319f4c292b4ef2ccb9c9bc27ae5ec856c6d","node_id":"C_kwDOU-sL-toAKDQxMDQyMzE5ZjRjMjkyYjRlZjJjY2I5YzliYzI3YWU1ZWM4NTZjNmQ","parents":[{"html_url":"https://github.com/eduardomds96/nexo-filmes/commit/794d73e021a1619d1923f22f035ba362d7481edb","sha":"794d73e021a1619d1923f22f035ba362d7481edb","url":"https://api.github.com/repos/eduardomds96/nexo-filmes/commits/794d73e021a1619d1923f22f035ba362d7481edb"}],"sha":"41042319f4c292b4ef2ccb9c9bc27ae5ec856c6d"